COMMENT ON COLUMN platform.tenant.status IS 'Tenant lifecycle state.';
COMMENT ON COLUMN platform.tenant.primary_email IS 'Main contact e-mail.';
COMMENT ON COLUMN platform.tenant.primary_phone IS 'Main contact phone.';
COMMENT ON COLUMN platform.tenant.country_id IS 'Country of registration.';
COMMENT ON COLUMN platform.tenant.default_currency_id IS 'Default currency for fees and payments.';
COMMENT ON COLUMN platform.tenant.timezone IS 'IANA time zone, e.g. Asia/Kolkata.';
