COMMENT ON COLUMN platform.tenant.created_at IS 'Row creation time.';
COMMENT ON COLUMN platform.tenant.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN platform.tenant.updated_at IS 'Last update time.';
