CREATE TABLE platform.file_object (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    storage_disk varchar(50) NOT NULL,
    storage_key text NOT NULL,
    storage_generation bigint,
    file_name varchar(255) NOT NULL,
    original_name varchar(255),
    mime_type varchar(150),
    size_bytes bigint NOT NULL,
    checksum_sha256 char(64),
    owner_entity_type varchar(80),
    owner_entity_id uuid,
    collection_name varchar(80),
    sort_order integer,
    file_kind varchar(30),
    is_shared boolean NOT NULL DEFAULT false,
    processing_status varchar(30) NOT NULL DEFAULT  'none',
    processing_attempts integer NOT NULL DEFAULT 0,
    processing_error text,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    status varchar(20) NOT NULL DEFAULT 'pending',
    scanned_at timestamptz,
    uploaded_by_user_id uuid,
    CONSTRAINT pk_file_object PRIMARY KEY (id),
    CONSTRAINT ck_file_object_size_bytes_rule CHECK (size_bytes>=0),
    CONSTRAINT ck_file_object_file_kind CHECK (file_kind IN ('document', 'presentation', 'spreadsheet', 'pdf', 'image', 'audio', 'video', 'archive', 'package', 'ebook', 'other')),
    CONSTRAINT ck_file_object_processing_status CHECK (processing_status IN ('none', 'pending', 'in_progress', 'succeeded', 'failed')),
    CONSTRAINT ck_file_object_status CHECK (status IN ('pending', 'available', 'quarantined', 'deleted')),
    CONSTRAINT uq_file_object_storage UNIQUE (storage_disk, storage_key),
    CONSTRAINT uq_file_object_id_tenant UNIQUE (id, tenant_id)
);
COMMENT ON TABLE platform.file_object IS 'Every stored file (documents, images, videos, attachments). Other tables reference files through *_file_id.';
COMMENT ON COLUMN platform.file_object.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN platform.file_object.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN platform.file_object.storage_disk IS 'Storage backend / bucket name.';
COMMENT ON COLUMN platform.file_object.storage_key IS 'Object key / path inside the storage backend.';
COMMENT ON COLUMN platform.file_object.storage_generation IS 'Generation of the stored object the file was completed with (the store''s version of the bytes); downloads, copies and reads use exactly that generation, so bytes written to the key later are never served. NULL while the upload is pending.';
COMMENT ON COLUMN platform.file_object.file_name IS 'Stored file name.';
COMMENT ON COLUMN platform.file_object.original_name IS 'Name of the file as uploaded.';
COMMENT ON COLUMN platform.file_object.mime_type IS 'MIME type.';
COMMENT ON COLUMN platform.file_object.size_bytes IS 'File size in bytes.';
COMMENT ON COLUMN platform.file_object.checksum_sha256 IS 'SHA-256 of the content.';
COMMENT ON COLUMN platform.file_object.owner_entity_type IS 'Polymorphic owner type (table name) when the file belongs to one record.';
COMMENT ON COLUMN platform.file_object.owner_entity_id IS 'Polymorphic owner record id (pairs with owner_entity_type).';
COMMENT ON COLUMN platform.file_object.collection_name IS 'Logical collection within the owner, e.g. avatar, gallery.';
COMMENT ON COLUMN platform.file_object.sort_order IS 'Order within the collection.';
COMMENT ON COLUMN platform.file_object.file_kind IS 'Kind of file (from the fixed content-type catalogue), used for icons, viewers and processing.';
COMMENT ON COLUMN platform.file_object.is_shared IS 'Shared with a group of users (readable beyond the owner).';
