COMMENT ON COLUMN platform.file_object.processing_attempts IS 'Processing attempts so far.';
COMMENT ON COLUMN platform.file_object.processing_error IS 'Last processing error.';
COMMENT ON COLUMN platform.file_object.created_at IS 'Row creation time.';
COMMENT ON COLUMN platform.file_object.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN platform.file_object.updated_at IS 'Last update time.';
COMMENT ON COLUMN platform.file_object.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN platform.file_object.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN platform.file_object.row_version IS 'Optimistic-locking version.';
COMMENT ON COLUMN platform.file_object.status IS 'Lifecycle: pending (upload started), available, quarantined (failed scanning), deleted (storage reclaimed).';
COMMENT ON COLUMN platform.file_object.scanned_at IS 'When malware/content scanning finished.';
COMMENT ON COLUMN platform.file_object.uploaded_by_user_id IS 'User who uploaded the file.';
CREATE INDEX ix_file_object_1 ON platform.file_object (owner_entity_type, owner_entity_id);

