) PARTITION BY RANGE (occurred_at);
CREATE TABLE platform.audit_log_default PARTITION OF platform.audit_log DEFAULT;
COMMENT ON TABLE platform.audit_log_default IS 'Default partition of platform.audit_log. Monthly partitions are created ahead of time by the application maintenance job, so this partition should stay empty.';
COMMENT ON TABLE platform.audit_log IS 'Immutable audit trail of changes and actions.';
COMMENT ON COLUMN platform.audit_log.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
