-- === R4 / P1-21 / P1-22: theme tokens as rows, typed subscription, file lifecycle ===

CREATE TABLE platform.theme_token (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    theme_id uuid NOT NULL,
    token_key varchar(60) NOT NULL,
    value varchar(200) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_theme_token PRIMARY KEY (id)
);
COMMENT ON TABLE platform.theme_token IS 'One design token of a theme (key -> value). A new token is a row, not a migration.';
COMMENT ON COLUMN platform.theme_token.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN platform.theme_token.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN platform.theme_token.theme_id IS 'Theme the token belongs to.';
COMMENT ON COLUMN platform.theme_token.token_key IS 'Token name (color.primary, font.heading...).';
COMMENT ON COLUMN platform.theme_token.value IS 'Token value.';
COMMENT ON COLUMN platform.theme_token.created_at IS 'Row creation time.';
COMMENT ON COLUMN platform.theme_token.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN platform.theme_token.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN platform.theme_token.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN platform.theme_token.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN platform.theme_token.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
ALTER TABLE platform.theme_token ADD CONSTRAINT fk_theme_token_theme_id FOREIGN KEY (theme_id, tenant_id) REFERENCES platform.theme (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_theme_token_theme_id ON platform.theme_token (theme_id);

-- === P1-04 / P1-11: document numbering, tenant domains ===

CREATE TABLE platform.tenant_domain (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    host varchar(255) NOT NULL,
    is_primary boolean NOT NULL DEFAULT false,
