    CONSTRAINT pk_tenant_domain PRIMARY KEY (id),
    CONSTRAINT uq_tenant_domain_host UNIQUE (host)
);
COMMENT ON TABLE platform.tenant_domain IS 'Host name a tenant is served on (subdomain or custom domain). Requests and deep links resolve the tenant from the host.';
COMMENT ON COLUMN platform.tenant_domain.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN platform.tenant_domain.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN platform.tenant_domain.host IS 'Fully-qualified host (unique across the platform).';
COMMENT ON COLUMN platform.tenant_domain.is_primary IS 'Canonical host used when generating links.';
COMMENT ON COLUMN platform.tenant_domain.is_verified IS 'Whether domain ownership was verified (custom domains).';
COMMENT ON COLUMN platform.tenant_domain.verified_at IS 'When verification succeeded.';
COMMENT ON COLUMN platform.tenant_domain.created_at IS 'Row creation time.';
COMMENT ON COLUMN platform.tenant_domain.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN platform.tenant_domain.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN platform.tenant_domain.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN platform.tenant_domain.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN platform.tenant_domain.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
CREATE UNIQUE INDEX uq_tenant_domain_primary ON platform.tenant_domain (tenant_id) WHERE is_primary AND deleted_at IS NULL;

-- === P1-12: sync/retention indexes ===

CREATE INDEX ix_deletion_log_tenant_deleted_at_ts ON platform.deletion_log (tenant_id, deleted_at_ts);

-- === P1-13: operations and idempotency ===

CREATE TABLE platform.operation (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    operation_name varchar(120) NOT NULL,
    resource_type varchar(80),
    resource_id uuid,
    status varchar(20) NOT NULL DEFAULT 'running',
    progress_percent smallint,
    error_code varchar(60),
    error_message varchar(500),
    result_entity_type varchar(80),
    result_entity_id uuid,
    started_by_user_id uuid,
    started_at timestamptz NOT NULL DEFAULT now(),
    finished_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_operation PRIMARY KEY (id),
    CONSTRAINT uq_operation_id_tenant UNIQUE (id, tenant_id),
    CONSTRAINT ck_operation_status CHECK (status IN ('running', 'succeeded', 'failed', 'cancelled'))
);
COMMENT ON TABLE platform.operation IS 'Long-running operations of the platform module (written directly) plus the job-centre index of every other module''s operations (replicated from their operation events; the owning module''s own operation table is authoritative). Polled by clients until finished.';
COMMENT ON COLUMN platform.operation.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN platform.operation.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN platform.operation.operation_name IS 'Operation id as exposed by the API (module.Method).';
COMMENT ON COLUMN platform.operation.resource_type IS 'Kind of resource being worked on.';
COMMENT ON COLUMN platform.operation.resource_id IS 'Id of that resource.';
COMMENT ON COLUMN platform.operation.status IS 'running / succeeded / failed / cancelled.';
COMMENT ON COLUMN platform.operation.progress_percent IS 'Progress, when the job reports it.';
COMMENT ON COLUMN platform.operation.error_code IS 'Machine error code when failed.';
COMMENT ON COLUMN platform.operation.error_message IS 'Human error summary when failed.';
COMMENT ON COLUMN platform.operation.result_entity_type IS 'Kind of the produced record.';
COMMENT ON COLUMN platform.operation.result_entity_id IS 'Id of the produced record.';
COMMENT ON COLUMN platform.operation.started_by_user_id IS 'User who started it.';
COMMENT ON COLUMN platform.operation.started_at IS 'Start time.';
COMMENT ON COLUMN platform.operation.finished_at IS 'End time.';
COMMENT ON COLUMN platform.operation.created_at IS 'Row creation time.';
COMMENT ON COLUMN platform.operation.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN platform.operation.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN platform.operation.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN platform.operation.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN platform.operation.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
CREATE TABLE platform.import_job (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    entity_type varchar(40) NOT NULL,
    institution_id uuid,
    file_id uuid NOT NULL,
    dry_run boolean NOT NULL DEFAULT false,
    row_count integer NOT NULL DEFAULT 0,
    batch_count integer NOT NULL DEFAULT 0,
    applied_batch_count integer NOT NULL DEFAULT 0,
    created_count integer NOT NULL DEFAULT 0,
    error_count integer NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_import_job PRIMARY KEY (id),
    CONSTRAINT uq_import_job_id_tenant UNIQUE (id, tenant_id),
    CONSTRAINT uq_import_job_operation UNIQUE (operation_id),
    CONSTRAINT ck_import_job_entity_type CHECK (entity_type IN ('students', 'guardians', 'staff', 'library_media', 'holidays', 'promotions')),
    CONSTRAINT ck_import_job_counts CHECK (row_count >= 0 AND batch_count >= 0 AND applied_batch_count BETWEEN 0 AND batch_count AND created_count BETWEEN 0 AND row_count AND error_count >= 0)
);
COMMENT ON TABLE platform.import_job IS 'One bulk import (platform.StartImport) of a CSV file: what it imports, where, and the running totals of its operation''s result. The rows are created by the module that owns them (platform.import.batch_requested → <module>.import.batch_applied); the platform keeps only counts and row errors.';
COMMENT ON COLUMN platform.import_job.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN platform.import_job.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN platform.import_job.operation_id IS 'The platform operation the import answers (one import per operation).';
COMMENT ON COLUMN platform.import_job.entity_type IS 'What is imported: students / guardians / staff / library_media / holidays / promotions.';
COMMENT ON COLUMN platform.import_job.institution_id IS 'Target institution (logical reference to org.institution); NULL for tenant-level records (guardians, tenant holidays).';
COMMENT ON COLUMN platform.import_job.file_id IS 'The uploaded CSV file.';
COMMENT ON COLUMN platform.import_job.dry_run IS 'Validated only: nothing was sent to the owning module.';
COMMENT ON COLUMN platform.import_job.row_count IS 'Data rows in the file.';
COMMENT ON COLUMN platform.import_job.batch_count IS 'Batches of valid rows sent to the owning module.';
COMMENT ON COLUMN platform.import_job.applied_batch_count IS 'Batches the owning module has answered; the import is finished when it reaches batch_count.';
COMMENT ON COLUMN platform.import_job.created_count IS 'Rows the owning module created.';
COMMENT ON COLUMN platform.import_job.error_count IS 'Row errors recorded (platform.import_row_error).';
COMMENT ON COLUMN platform.import_job.created_at IS 'Row creation time.';
COMMENT ON COLUMN platform.import_job.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN platform.import_job.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN platform.import_job.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN platform.import_job.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN platform.import_job.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
CREATE TABLE platform.import_batch (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    import_job_id uuid NOT NULL,
    batch_number integer NOT NULL,
    module_code varchar(40) NOT NULL,
    created_count integer NOT NULL,
    error_count integer NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_import_batch PRIMARY KEY (id),
    CONSTRAINT uq_import_batch_number UNIQUE (import_job_id, batch_number),
    CONSTRAINT ck_import_batch_counts CHECK (batch_number >= 1 AND created_count >= 0 AND error_count >= 0)
);
COMMENT ON TABLE platform.import_batch IS 'A batch of an import that its owning module has answered (one row per batch: a repeated answer is ignored).';
COMMENT ON COLUMN platform.import_batch.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN platform.import_batch.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN platform.import_batch.import_job_id IS 'The import.';
COMMENT ON COLUMN platform.import_batch.batch_number IS '1-based position of the batch in the import.';
COMMENT ON COLUMN platform.import_batch.module_code IS 'The module that answered (the owner of the entity type).';
COMMENT ON COLUMN platform.import_batch.created_count IS 'Rows of the batch the module created.';
COMMENT ON COLUMN platform.import_batch.error_count IS 'Row errors of the batch the module reported.';
COMMENT ON COLUMN platform.import_batch.created_at IS 'Row creation time (when the answer arrived).';
COMMENT ON COLUMN platform.import_batch.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN platform.import_batch.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN platform.import_batch.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN platform.import_batch.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN platform.import_batch.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
CREATE TABLE platform.import_row_error (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    import_job_id uuid NOT NULL,
    batch_number integer,
    row_number integer NOT NULL,
    field varchar(80),
    message varchar(500) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_import_row_error PRIMARY KEY (id),
    CONSTRAINT ck_import_row_error_row CHECK (row_number >= 1 AND (batch_number IS NULL OR batch_number >= 1))
);
COMMENT ON TABLE platform.import_row_error IS 'Why a row of an import was refused: by the platform''s template check (no batch) or by the owning module (its batch). Messages name fields, never cell values.';
COMMENT ON COLUMN platform.import_row_error.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN platform.import_row_error.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN platform.import_row_error.import_job_id IS 'The import.';
COMMENT ON COLUMN platform.import_row_error.batch_number IS 'The batch whose module refused the row; NULL when the platform''s template check did.';
COMMENT ON COLUMN platform.import_row_error.row_number IS 'Record number of the row in the file (the header row is 1, as a spreadsheet numbers rows).';
COMMENT ON COLUMN platform.import_row_error.field IS 'The column at fault; NULL for the row as a whole.';
COMMENT ON COLUMN platform.import_row_error.message IS 'Why the row was refused.';
COMMENT ON COLUMN platform.import_row_error.created_at IS 'Row creation time.';
COMMENT ON COLUMN platform.import_row_error.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN platform.import_row_error.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN platform.import_row_error.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN platform.import_row_error.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN platform.import_row_error.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
