CREATE TABLE platform.idempotency_key (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    idempotency_key uuid NOT NULL,
    user_id uuid,
    operation_name varchar(120) NOT NULL,
    request_hash varchar(64),
    response_status smallint,
    response_body text,
    locked_at timestamptz,
    completed_at timestamptz,
    expires_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_idempotency_key PRIMARY KEY (id),
    CONSTRAINT uq_idempotency_key_1 UNIQUE (tenant_id, idempotency_key)
);
COMMENT ON TABLE platform.idempotency_key IS 'Stored outcome of a write carrying an Idempotency-Key; replays return the stored response. Rows expire after 24h (cleanup job).';
COMMENT ON COLUMN platform.idempotency_key.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN platform.idempotency_key.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN platform.idempotency_key.idempotency_key IS 'Key sent by the client.';
COMMENT ON COLUMN platform.idempotency_key.user_id IS 'Caller.';
COMMENT ON COLUMN platform.idempotency_key.operation_name IS 'Operation the key was used on.';
COMMENT ON COLUMN platform.idempotency_key.request_hash IS 'Hash of the request body; a replay with a different body is rejected.';
COMMENT ON COLUMN platform.idempotency_key.response_status IS 'Stored HTTP status.';
COMMENT ON COLUMN platform.idempotency_key.response_body IS 'Stored response body.';
COMMENT ON COLUMN platform.idempotency_key.locked_at IS 'Set while the first attempt is still executing.';
COMMENT ON COLUMN platform.idempotency_key.completed_at IS 'When the stored response was written.';
COMMENT ON COLUMN platform.idempotency_key.expires_at IS 'When the row may be purged.';
COMMENT ON COLUMN platform.idempotency_key.created_at IS 'Row creation time.';
COMMENT ON COLUMN platform.idempotency_key.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN platform.idempotency_key.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN platform.idempotency_key.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN platform.idempotency_key.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN platform.idempotency_key.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';

-- === P1-13: transactional outbox / inbox ===

CREATE TABLE platform.outbox_event (
    id bigint GENERATED ALWAYS AS IDENTITY,
    tenant_id uuid,
    event_type varchar(120) NOT NULL,
    aggregate_type varchar(80) NOT NULL,
    aggregate_id uuid NOT NULL,
    payload text NOT NULL,
    occurred_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    publish_error text,
    CONSTRAINT pk_platform_outbox_event PRIMARY KEY (id)
);
COMMENT ON TABLE platform.outbox_event IS 'Transactional outbox of the platform module: events written in the same transaction as the change, published to the bus by a relay, then pruned. Ordered by the identity column.';
COMMENT ON COLUMN platform.outbox_event.id IS 'Monotonic sequence; publish order.';
COMMENT ON COLUMN platform.outbox_event.tenant_id IS 'Owning tenant (customer organisation). Row-level security key. NULL for global data changed by platform staff: such rows are invisible to every tenant session.';
COMMENT ON COLUMN platform.outbox_event.event_type IS 'Event name (module.entity.verb).';
COMMENT ON COLUMN platform.outbox_event.aggregate_type IS 'Entity kind the event is about.';
COMMENT ON COLUMN platform.outbox_event.aggregate_id IS 'Entity id the event is about.';
COMMENT ON COLUMN platform.outbox_event.payload IS 'Serialised event (opaque message envelope).';
COMMENT ON COLUMN platform.outbox_event.occurred_at IS 'When the change committed.';
COMMENT ON COLUMN platform.outbox_event.published_at IS 'When the relay published it (NULL = pending).';
COMMENT ON COLUMN platform.outbox_event.publish_error IS 'Why the relay could not turn the row into an event (set aside, not published); NULL otherwise.';
CREATE INDEX ix_platform_outbox_event_pending ON platform.outbox_event (id) WHERE published_at IS NULL AND publish_error IS NULL;
CREATE TABLE platform.inbox_event (
    event_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    event_type varchar(120) NOT NULL,
    received_at timestamptz NOT NULL DEFAULT now(),
    processed_at timestamptz,
    processing_error text,
    CONSTRAINT pk_platform_inbox_event PRIMARY KEY (tenant_id, event_id)
);
COMMENT ON TABLE platform.inbox_event IS 'Inbox of the platform module: ids of consumed events, kept so redeliveries are processed exactly once.';
COMMENT ON COLUMN platform.inbox_event.event_id IS 'Global id of the consumed event; recorded per tenant.';
COMMENT ON COLUMN platform.inbox_event.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN platform.inbox_event.event_type IS 'Event name.';
COMMENT ON COLUMN platform.inbox_event.received_at IS 'First delivery time.';
COMMENT ON COLUMN platform.inbox_event.processed_at IS 'When handling committed (NULL = in flight).';
COMMENT ON COLUMN platform.inbox_event.processing_error IS 'Last handling error, if any.';
CREATE INDEX ix_platform_inbox_event_processed ON platform.inbox_event (processed_at) WHERE processed_at IS NOT NULL;

