-- === P0-03: row-level security (tenant isolation). The application role is not the table owner and sets app.tenant_id per transaction; a platform-admin role with BYPASSRLS serves cross-tenant operations ===

ALTER TABLE platform.audit_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE platform.audit_log FORCE ROW LEVEL SECURITY;
-- a tenant's rows, to that tenant only (NULLIF: a pooled connection that bound a tenant before reads back '')
CREATE POLICY tenant_isolation ON platform.audit_log
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
-- a row of global data, written only by a transaction that binds no tenant; no tenant session can forge one
CREATE POLICY global_insert ON platform.audit_log FOR INSERT
    WITH CHECK (tenant_id IS NULL AND NULLIF(current_setting('app.tenant_id', true), '') IS NULL);
-- the same rows, readable by a transaction that binds no tenant (platform staff): the idempotent insert
-- (ON CONFLICT DO NOTHING) needs it, and a tenant session still sees none of them
CREATE POLICY global_read ON platform.audit_log FOR SELECT
    USING (tenant_id IS NULL AND NULLIF(current_setting('app.tenant_id', true), '') IS NULL);
ALTER TABLE platform.deletion_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE platform.deletion_log FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON platform.deletion_log USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
ALTER TABLE platform.entity_attachment ENABLE ROW LEVEL SECURITY;
ALTER TABLE platform.entity_attachment FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON platform.entity_attachment USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
ALTER TABLE platform.entity_note ENABLE ROW LEVEL SECURITY;
