ALTER TABLE platform.idempotency_key FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON platform.idempotency_key USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
ALTER TABLE platform.inbox_event ENABLE ROW LEVEL SECURITY;
ALTER TABLE platform.inbox_event FORCE ROW LEVEL SECURITY;
