ALTER TABLE platform.import_job ENABLE ROW LEVEL SECURITY;
ALTER TABLE platform.import_job FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON platform.import_job USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
ALTER TABLE platform.import_batch ENABLE ROW LEVEL SECURITY;
ALTER TABLE platform.import_batch FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON platform.import_batch USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
ALTER TABLE platform.import_row_error ENABLE ROW LEVEL SECURITY;
ALTER TABLE platform.import_row_error FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON platform.import_row_error USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
ALTER TABLE platform.outbox_event ENABLE ROW LEVEL SECURITY;
ALTER TABLE platform.outbox_event FORCE ROW LEVEL SECURITY;
-- a tenant's rows, to that tenant only (NULLIF: a pooled connection that bound a tenant before reads back '')
CREATE POLICY tenant_isolation ON platform.outbox_event
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
-- a row of global data, written only by a transaction that binds no tenant; no tenant session can forge one
CREATE POLICY global_insert ON platform.outbox_event FOR INSERT
    WITH CHECK (tenant_id IS NULL AND NULLIF(current_setting('app.tenant_id', true), '') IS NULL);
